#!/usr/bin/env node
// Builds every generated file of the design system from its sources. No dependencies.
//
//   sources:   src/index.js · src/index.d.ts · src/styles.css · src/base.css
//              project/tokens.json · project/fonts/ · project/assets/
//   package:   dist/  (what `npm install github:…#vX.Y.Z` gives the front)
//   artifact:  project/components/bundle.js · bundle.css · index.d.ts  (claude.ai artifact + GitHub Pages site)
//
//   node scripts/build.mjs           write everything
//   node scripts/build.mjs --check   fail if any generated file is missing, stale or extra
import { readFileSync, writeFileSync, mkdirSync, readdirSync, statSync, rmSync, existsSync } from 'node:fs';
import { dirname, join, relative, basename } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const CHECK = process.argv.includes('--check');
const r = (p) => join(ROOT, p);
const text = (p) => readFileSync(r(p), 'utf8');
const pkg = JSON.parse(text('package.json'));
const out = new Map(); // relative path → Buffer | string

/* ---------- Components ---------- */
const src = text('src/index.js');
const exportMatch = /\nexport \{\s*([\s\S]*?)\s*\};\s*$/.exec(src);
if (!exportMatch) throw new Error('src/index.js must end with one `export { … };` block');
const names = exportMatch[1].split(',').map((s) => s.trim()).filter(Boolean);
const components = names.filter((n) => /^[A-Z]/.test(n) && n !== 'ICONS');
const banner = `/*! ${pkg.name} v${pkg.version} — ${pkg.license} License (see LICENSE). Generated by scripts/build.mjs from src/index.js; do not edit. */\n`;

out.set('dist/index.js', banner + src);

const body = src
  .slice(0, exportMatch.index)
  .replace(/^\/\/.*\n/gm, '')
  .replace(/^import React from 'react';\n/m, '')
  .trim()
  .split('\n').map((l) => (l ? '  ' + l : l)).join('\n');
const header = `/* @ds-bundle: ${JSON.stringify({ format: 4, namespace: 'Matrimonio', components: components.map((name) => ({ name })) })} */`;
const iife = `${header}
/* ${pkg.name} v${pkg.version} — generated by scripts/build.mjs from src/index.js; do not edit. */
(function () {
  'use strict';
  var React = window.React;
${body}

  window.Matrimonio = Object.assign(window.Matrimonio || {}, {
    ${names.map((n) => `${n}: ${n}`).join(', ')}
  });
})();
`;
if (/<\/script|<!--/i.test(iife)) throw new Error('bundle.js must not contain </script or <!--');
out.set('project/components/bundle.js', iife);

/* ---------- Types ---------- */
const dts = text('src/index.d.ts');
out.set('dist/index.d.ts', dts);
out.set('project/components/index.d.ts', dts);

/* ---------- Styles ---------- */
const styles = text('src/styles.css');
const base = text('src/base.css');
for (const [name, css] of [['styles.css', styles], ['base.css', base]]) {
  if (/<\/style/i.test(css)) throw new Error(`${name} must not contain </style`);
  out.set(`dist/${name}`, css);
}
out.set('project/components/bundle.css', `/* Matrimonio — artifact stylesheet = src/base.css + src/styles.css. Generated by scripts/build.mjs; do not edit. */\n${base}\n${styles}`);

/* ---------- Tokens ---------- */
const tokens = JSON.parse(text('project/tokens.json'));
out.set('dist/tokens.json', JSON.stringify(tokens, null, 2) + '\n');
const val = (v) => (/^\{.+\}$/.test(v) ? `var(--${v.slice(1, -1)})` : v);
const len = (v) => (typeof v === 'number' ? `${v}px` : v);
const themes = tokens.color.themes.map((t) => t.id);
const css = [`/* ${pkg.name} v${pkg.version} — tokens. Generated by scripts/build.mjs from project/tokens.json; do not edit. */`];
css.push(`:root, [data-theme="${themes[0]}"] {`);
for (const t of tokens.color.tokens) css.push(`  --${t.name}: ${val(typeof t.value === 'string' ? t.value : t.value[themes[0]])};`);
for (const t of tokens.shadow?.tokens ?? []) css.push(`  --${t.name}: ${typeof t.value === 'string' ? t.value : t.value[themes[0]]};`);
css.push('}');
for (const id of themes.slice(1)) {
  css.push(`[data-theme="${id}"] {`, `  color-scheme: ${id === 'dark' ? 'dark' : 'light'};`);
  for (const t of tokens.color.tokens) if (typeof t.value === 'object' && t.value[id]) css.push(`  --${t.name}: ${val(t.value[id])};`);
  for (const t of tokens.shadow?.tokens ?? []) if (typeof t.value === 'object' && t.value[id]) css.push(`  --${t.name}: ${t.value[id]};`);
  css.push('}');
}
css.push(':root {');
for (const [key, fam] of Object.entries(tokens)) {
  if (['color', 'shadow', 'type'].includes(key) || !fam?.tokens) continue;
  for (const t of fam.tokens) css.push(`  --${t.name}: ${len(t.value)};`);
}
for (const [k, stack] of Object.entries(tokens.type.families)) css.push(`  --font-${k}: ${stack};`);
css.push('}');
for (const f of tokens.type.fonts) {
  css.push(`@font-face { font-family: '${f.family}'; src: url('./fonts/${basename(f.file)}') format('woff2'); font-weight: ${f.weight}; font-style: ${f.style || 'normal'}; font-display: swap; }`);
}
for (const g of tokens.type.groups) {
  for (const s of g.styles) {
    const decl = [`font-family: var(--font-${s.family || g.family})`, `font-size: ${len(s.fontSize)}`, `line-height: ${s.lineHeight}`, `font-weight: ${s.fontWeight}`];
    if (s.letterSpacing) decl.push(`letter-spacing: ${s.letterSpacing}`);
    css.push(`.mx-type-${s.name} { ${decl.join('; ')}; }`);
  }
}
out.set('dist/tokens.css', css.join('\n') + '\n');

/* ---------- Fonts and assets (binary copies) ---------- */
function walk(dir) {
  return readdirSync(r(dir)).sort().flatMap((name) => {
    const p = join(dir, name);
    if (name.startsWith('.')) return [];
    return statSync(r(p)).isDirectory() ? walk(p) : [p];
  });
}
for (const p of walk('project/fonts')) out.set(join('dist/fonts', relative('project/fonts', p)), readFileSync(r(p)));
for (const p of walk('project/assets')) if (p.endsWith('.svg')) out.set(join('dist/assets', relative('project/assets', p)), readFileSync(r(p)));

/* ---------- Write or check ---------- */
const same = (a, b) => Buffer.compare(Buffer.isBuffer(a) ? a : Buffer.from(a), b) === 0;
const problems = [];
for (const [p, content] of out) {
  if (!existsSync(r(p))) problems.push(`missing  ${p}`);
  else if (!same(content, readFileSync(r(p)))) problems.push(`stale    ${p}`);
}
const extra = existsSync(r('dist')) ? walk('dist').filter((p) => !out.has(p)) : [];
for (const p of extra) problems.push(`extra    ${p}`);

if (CHECK) {
  if (problems.length) {
    console.error(`Generated files are out of date — run \`node scripts/build.mjs\` and commit:\n  ${problems.join('\n  ')}`);
    process.exit(1);
  }
  console.log(`OK — ${out.size} generated files are up to date (v${pkg.version}).`);
} else {
  for (const p of extra) rmSync(r(p));
  for (const [p, content] of out) {
    mkdirSync(dirname(r(p)), { recursive: true });
    writeFileSync(r(p), content);
  }
  console.log(`Built ${out.size} files for v${pkg.version} (${components.length} components): ${problems.length} changed.`);
}
